\draw[->] (0,0)--(0,6) node[above] {$f$};
\draw[blue,thick,domain=0.7:3.3,samples=60] plot (\x,{0.5*(\x-2)^2+0.5*(\x-2)+4});
\draw[orange,thick] (1,3.5)--(3,4.5);
\fill (2,4) circle (2pt) node[above left] {$P(2,4)$};
\node[left] at (-0.3,3.5) {$(1,3.5)$};
