[tikz]
\begin{tikzpicture}
\draw[->] (0,0)--(4,0) node[right] {$x$};
\draw[->] (0,0)--(0,7) node[above] {$f$};
\draw[blue,thick,domain=0.7:3.3,samples=60] plot (\x,{0.5*(\x-2)^2-1.5*(\x-2)+4});
\draw[orange,thick] (1,5.5)--(3,2.5);
